import type { Request, Response } from 'express';

export interface Product {
  id: string;
  name: string;
  category: 'pottery' | 'textiles' | 'woodwork' | 'jewelry';
  price: number;
  image: string;
  featured: boolean;
  description: string;
}

const products: Product[] = [
  // Pottery
  {
    id: 'p1',
    name: 'Stoneware Serving Bowl',
    category: 'pottery',
    price: 68,
    image: '/airo-assets/images/products/pottery-bowl',
