    id: 't2',
    name: 'Woven Storage Basket',
    category: 'textiles',
    price: 52,
    image: '/airo-assets/images/products/textiles-basket',
    featured: false,
    description: 'Natural seagrass basket, hand-woven by artisans in a small coastal cooperative.',
  },
  {
    id: 't3',
    name: 'Linen Cushion Cover',
    category: 'textiles',
    price: 44,
    image: '/airo-assets/images/products/textiles-cushion',
