    name: 'Stone Pendant Necklace',
    category: 'jewelry',
    price: 76,
    image: '/airo-assets/images/products/jewelry-necklace',
    featured: false,
    description: 'Labradorite pendant set in oxidized silver on a delicate chain.',
  },
  {
    id: 'j3',
    name: 'Hammered Hoop Earrings',
    category: 'jewelry',
    price: 42,
    image: '/airo-assets/images/products/jewelry-earrings',
    featured: false,
    description: 'Lightweight hammered brass hoops with a warm, antique finish.',
  },
];

export default function handler(req: Request, res: Response) {
  const { category, featured } = req.query;

  let result = [...products];

  if (category && typeof category === 'string') {
    result = result.filter((p) => p.category === category.toLowerCase());
  }

  if (featured === 'true') {
    result = result.filter((p) => p.featured);
  }

  res.json(result);
}

