export async function fetchProducts(params?: {
  category?: string;
  featured?: boolean;
}): Promise<Product[]> {
  const url = new URL('/api/products', typeof window !== 'undefined' ? window.location.origin : 'http://localhost:3000');

  if (params?.category) url.searchParams.set('category', params.category);
  if (params?.featured) url.searchParams.set('featured', 'true');

  const res = await fetch(url.pathname + url.search);
  if (!res.ok) throw new Response(null, { status: res.status });
  return res.json() as Promise<Product[]>;
}

